use serde::Serialize;

#[derive(Debug, Serialize, serde::Deserialize, PartialEq)]
enum Renamed {
    #[serde(rename = "a\"b")]
    Unit,
    #[serde(rename = "x\ny")]
    Tuple(u8),
    #[serde(rename = "x\\y")]
    Object { a: u8 },
}

#[derive(Debug, Serialize, serde::Deserialize, PartialEq)]
struct EscapedField {
    #[serde(rename = "a\"b")]
