#[test]
fn serde_empty_unknown_length_sequence_roundtrip() {
    let value = std::iter::empty::<u8>();
    struct Sequence<I>(I);
    impl<I> Serialize for Sequence<I>
    where I: Clone + Iterator<Item = u8> {
        fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
            use serde::ser::SerializeSeq;
            let mut seq = serializer.serialize_seq(None)?;
            for value in self.0.clone() { seq.serialize_element(&value)?; }
            seq.end()
        }
    }
    let expected = serde_json::to_string(&Sequence(value)).unwrap();
    let actual = simd_json::to_string(&Sequence(value)).unwrap();
    println!("expected={expected:?}, actual={actual:?}");
    assert_eq!(actual, expected);
}
